  [
    {
      "fieldName": "ucinn_ascendv2__Excluded_Address_Relation_Statuses_v1__c",
      "toolTip": "Enter a JSON list of address relation statuses which should not be bubbled up to appear on the overview. The leftmost value will be what other address relation statuses are set to when multiple current address relations are disabled. If blank, all statuses will bubble up.",
      "jsonFieldParams": {
        "type": "list",
        "listType": "value",
        "helpText": "Enter a JSON list of address relation statuses which should not be bubbled up to appear on the overview. The leftmost value will be what other address relation statuses are set to when multiple current address relations are disabled. If blank, all statuses will bubble up.",
        "label": "Excluded Address Relation Statuses",
        "valueCustomFieldParams": {
          "type": "text"
        }
      }
    },
    {
      "fieldName": "BLANK_Excluded_Address_Relation_Statuse"
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__SmartyStreets_US_Field_Map__c",
      "toolTip": "Example: {\"DPV_Match_Code__c\":{\"analysis\":\"dpv_match_code\"}, \"DPV_Vacant__c\":{\"analysis\":\"dpv_vacant\"}, \"Active__c\":{\"analysis\":\"active\"}}",
