    {
      "fieldName": "ucinn_ascendv2__Enable_International_Autocomplete__c",
      "toolTip": "Enables International Autocomplete and country picklist next to auto complete lookup. Currently leveraged by SmartyStreets International Autocomplete API.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Enable International Autocomplete"
      }
    }
  ],
