    {
      "fieldName": "ucinn_ascendv2__SmartyStreets_Match_Method__c",
      "toolTip": "For US Address Verification.\n\nstrict - The API will return detailed output only if a valid match is found.\ninvalid - The API will return detailed output for both valid and invalid addresses.\n enhanced - The API will return detailed output based on a more aggressive matching mechanism. Only available with us-core-cloud license.",
      "customFieldParams": {
        "type": "picklist",
        "label": "SmartyStreets Match Method",
        "customPicklistValuesString": [
          "strict",
          "invalid",
          "enhanced"
        ]
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__SmartyStreets_Country_Code_Map__c",
      "toolTip": "Map of supported SmartyStreets countries to their corresponding ISO3 codes which are required to make callouts to the SmartyStreets international autocomplete API.",
      "jsonFieldParams": {
        "type": "object",
        "label": "SmartyStreets Country Code Map",
