          {
            "key": "[CUSTOM]",
            "valueCustomFieldParams": {
              "type": "text"
            }
          }
        ]
      }
    },
    {
      "fieldName": "ucinn_ascendv2__SmartyStreet_Timeout_Limit__c",
      "toolTip": "The time in seconds to wait for a response from Smarty. The minimum is 1 second and the maximum is 120 seconds.",
      "customFieldParams": {
        "type": "number",
        "label": "SmartyStreets Timeout Limit"
      }
    }
  ],
